CREATE TABLE `raw_evidence` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`collection_task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`collection_subquery_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`file_asset_id` CHAR(36) CHARACTER SET ascii NOT NULL,`source_url` VARCHAR(2048) NOT NULL,`canonical_url` VARCHAR(2048) NOT NULL,`dedupe_key` VARCHAR(200) CHARACTER SET ascii NOT NULL,`content_sha256` CHAR(64) CHARACTER SET ascii NOT NULL,`content_type` VARCHAR(181) CHARACTER SET ascii NOT NULL,`size_bytes` BIGINT UNSIGNED NOT NULL,`captured_at` DATETIME(3) NOT NULL,`parser_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`adapter_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`retention_until` DATETIME(3) NOT NULL,`status` ENUM('active','quarantined','expired') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_raw_evidence_scope_dedupe` (`organization_id`,`workspace_id`,`provider_id`,`dedupe_key`),UNIQUE KEY `uq_raw_evidence_file` (`file_asset_id`),KEY `idx_raw_evidence_scope_time` (`organization_id`,`workspace_id`,`captured_at`),KEY `idx_raw_evidence_task` (`collection_task_id`,`collection_subquery_id`),KEY `idx_raw_evidence_retention` (`status`,`retention_until`),KEY `idx_raw_evidence_hash` (`content_sha256`),CONSTRAINT `fk_raw_evidence_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_raw_evidence_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_raw_evidence_task` FOREIGN KEY (`collection_task_id`) REFERENCES `collection_tasks` (`id`),CONSTRAINT `fk_raw_evidence_subquery` FOREIGN KEY (`collection_subquery_id`) REFERENCES `collection_subqueries` (`id`),CONSTRAINT `fk_raw_evidence_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_raw_evidence_file` FOREIGN KEY (`file_asset_id`) REFERENCES `file_assets` (`id`),CONSTRAINT `fk_raw_evidence_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `normalized_records` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`raw_evidence_id` CHAR(36) CHARACTER SET ascii NOT NULL,`record_key` VARCHAR(200) CHARACTER SET ascii NOT NULL,`schema_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`record_version` INT UNSIGNED NOT NULL,`payload_json` JSON NOT NULL,`supersedes_record_id` CHAR(36) CHARACTER SET ascii NULL,`correction_reason` VARCHAR(500) NULL,`status` ENUM('active','superseded','quarantined') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_normalized_scope_record_version` (`organization_id`,`workspace_id`,`provider_id`,`record_key`,`record_version`),KEY `idx_normalized_scope_status` (`organization_id`,`workspace_id`,`status`,`created_at`),KEY `idx_normalized_evidence` (`raw_evidence_id`),KEY `idx_normalized_supersedes` (`supersedes_record_id`),CONSTRAINT `fk_normalized_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_normalized_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_normalized_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_normalized_evidence` FOREIGN KEY (`raw_evidence_id`) REFERENCES `raw_evidence` (`id`),CONSTRAINT `fk_normalized_supersedes` FOREIGN KEY (`supersedes_record_id`) REFERENCES `normalized_records` (`id`),CONSTRAINT `fk_normalized_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `field_provenance` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`normalized_record_id` CHAR(36) CHARACTER SET ascii NOT NULL,`raw_evidence_id` CHAR(36) CHARACTER SET ascii NOT NULL,`field_path` VARCHAR(200) CHARACTER SET ascii NOT NULL,`source_path` VARCHAR(200) CHARACTER SET ascii NOT NULL,`transform_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`source_value_sha256` CHAR(64) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_field_provenance_record_field` (`normalized_record_id`,`field_path`),KEY `idx_field_provenance_scope` (`organization_id`,`workspace_id`,`field_path`),KEY `idx_field_provenance_evidence` (`raw_evidence_id`),CONSTRAINT `fk_field_provenance_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_field_provenance_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_field_provenance_record` FOREIGN KEY (`normalized_record_id`) REFERENCES `normalized_records` (`id`),CONSTRAINT `fk_field_provenance_evidence` FOREIGN KEY (`raw_evidence_id`) REFERENCES `raw_evidence` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `reconciliation_runs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`parser_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`market` VARCHAR(40) CHARACTER SET ascii NOT NULL,`window_started_at` DATETIME(3) NOT NULL,`window_ended_at` DATETIME(3) NOT NULL,`sample_count` INT UNSIGNED NOT NULL,`metrics_json` JSON NOT NULL,`status` ENUM('passed','failed','insufficient_sample') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_reconciliation_scope_time` (`organization_id`,`workspace_id`,`created_at`),KEY `idx_reconciliation_provider_window` (`provider_id`,`parser_version`,`market`,`window_ended_at`),CONSTRAINT `fk_reconciliation_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_reconciliation_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_reconciliation_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_reconciliation_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `data_quality_issues` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`reconciliation_run_id` CHAR(36) CHARACTER SET ascii NULL,`raw_evidence_id` CHAR(36) CHARACTER SET ascii NULL,`normalized_record_id` CHAR(36) CHARACTER SET ascii NULL,`metric_code` VARCHAR(80) CHARACTER SET ascii NOT NULL,`field_path` VARCHAR(200) CHARACTER SET ascii NULL,`severity` ENUM('warning','critical') NOT NULL,`status` ENUM('open','resolved') NOT NULL,`actual_value` DECIMAL(12,8) NULL,`threshold_value` DECIMAL(12,8) NULL,`details_json` JSON NOT NULL,`resolved_by` CHAR(36) CHARACTER SET ascii NULL,`resolution_reason` VARCHAR(500) NULL,`resolved_at` DATETIME(3) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_quality_issue_scope_status` (`organization_id`,`workspace_id`,`status`,`severity`,`updated_at`),KEY `idx_quality_issue_provider_metric` (`provider_id`,`metric_code`,`created_at`),CONSTRAINT `fk_quality_issue_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_quality_issue_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_quality_issue_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_quality_issue_run` FOREIGN KEY (`reconciliation_run_id`) REFERENCES `reconciliation_runs` (`id`),CONSTRAINT `fk_quality_issue_evidence` FOREIGN KEY (`raw_evidence_id`) REFERENCES `raw_evidence` (`id`),CONSTRAINT `fk_quality_issue_record` FOREIGN KEY (`normalized_record_id`) REFERENCES `normalized_records` (`id`),CONSTRAINT `fk_quality_issue_resolver` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `evidence_data_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(100) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(80) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_type` ENUM('user','worker','system') NOT NULL,`actor_id` VARCHAR(160) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_evidence_event_scope_time` (`organization_id`,`workspace_id`,`occurred_at`),KEY `idx_evidence_event_resource` (`resource_type`,`resource_id`,`occurred_at`),KEY `idx_evidence_event_trace` (`trace_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
