CREATE TABLE `evidence_data_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` VARCHAR(160) CHARACTER SET ascii NOT NULL,`route` VARCHAR(220) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_evidence_operation` (`actor_id`,`route`,`idempotency_key`),KEY `idx_evidence_operation_resource` (`resource_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
